// READ-ONLY. GET urls only. One project per run (4 at once OOMs).
const PROJECT = '60625870676151e1da46d0.81913446'; // My QR Code
return [{ json: { url: 'https://api.lokalise.com/api2/projects/' + PROJECT + '/languages?limit=500' } }];

const PSEUDO = new Set(['pst','ps','cus','pt_old']);
const out = [];
for (const it of $input.all()) {
  const b = it.json.body !== undefined ? it.json.body : it.json;
  if (!Array.isArray(b.languages)) { throw new Error('languages missing: ' + JSON.stringify(b).slice(0,300)); }
  const ids = b.languages.filter(l => !PSEUDO.has(l.lang_iso)).map(l => l.lang_id);
  out.push({ json: { project_id: b.project_id, n_langs: ids.length,
    url: 'https://api.lokalise.com/api2/projects/' + b.project_id + '/keys?include_translations=1&disable_references=1&limit=500&pagination=cursor&filter_translation_lang_ids=' + ids.join(',') } });
}
return out;

const PSEUDO = new Set(['pst','ps','cus','pt_old']);
const LINGUISTS = new Set(['sabrathan@gmail.com','farahputri@gmail.com','dmluciahorea@gmail.com','roxanamoldovan25@gmail.com','mteres@terestraducciones.com','arandatrad@gmail.com','sara.guinot.trad@gmail.com','daniel@dgmultilingualservices.com','root-translations@outlook.com','austra.muizniece@gmail.com','harald.roald@gmail.com','47natcha@gmail.com','ellen.de.venter@outlook.com','ilaria.roncaglia@gmail.com','silke.luehrmann@gmx.de','boh.vozniuk@gmail.com','vidiasc@gmail.com','ivanaturcin@ymail.com','julius.valkiunas@gmail.com','jaromirvicari@me.com','karahansisman@gmail.com','katri.varvikko@gmail.com','kenneth@phraseit.dk','translation@cornell.hu','ruckova.lucia@gmail.com','marit.teichmann@gmail.com','michal.tosza@translators.org.pl','mteixeira@sacradomus.com','bruno@bsttranslations.com','nerissaneptuno@gmail.com','straus.translations@gmail.com','quentinnguyen.localize@gmail.com','therese.svardsten@gmail.com']);
const PROBES = ['contact us','download','log in','sign up','continue','cancel subscription','select a payment method','forgot password?','forgot your password?','congratulations!','try again','get started','settings','delete','save changes','upload','next','back','my account','your account','email address','subscribe now','start test','see results','create qr code','terms of use','privacy policy','dashboard','welcome back!','payment details','enter your email','close','terms and conditions','frequently asked questions','how it works','cancel anytime','download qr code','edit','log out'];
const PROBESET = new Set(PROBES);
const MONTH = /\b(January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\b/;
function clean(s) {
  return String(s).replace(/<[^>]+>/g,' ').replace(/\[%[^\]]*\]/g,'X').replace(/\{\{[^}]*\}\}/g,'X').replace(/\{[^}]*\}/g,'X').replace(/%\{[^}]*\}/g,'X').replace(/%\d*\$?[sdf]/g,'X').replace(/&nbsp;/g,'\u00A0').replace(/&amp;/g,'&');
}
const L = {};
const meta = {}; const errors = [];
function S(iso) {
  if (!L[iso]) L[iso] = { n:0, human:0, quotes:{}, apos:{straight:0, curly:0}, before:{'?':{},'!':{},':':{},';':{}}, ellipsis:{char:0, dots:0}, amp:{kept:0, dropped:0}, dec:{comma:0, dot:0}, thou:{dot:0, space:0, nbsp:0, nnbsp:0, comma:0, apos:0}, cur:{after_space:0, after_nbsp:0, after_none:0, before_space:0, before_none:0}, pct:{space:0, nbsp:0, none:0}, excl:{kept:0, dropped:0}, nbspStrings:0, nnbspStrings:0, time:[], date:[], probes:{}, reg:[] };
  return L[iso];
}
function bump(o,k){ o[k]=(o[k]||0)+1; }
for (const p of $input.all()) {
  const r = p.json || {}; const body = (r.body !== undefined ? r.body : r) || {};
  if (!Array.isArray(body.keys)) { errors.push({ status: r.statusCode, body: JSON.stringify(body).slice(0,200) }); continue; }
  const pid = body.project_id; meta[pid] = meta[pid] || { pages:0, keys:0 }; meta[pid].pages++;
  for (const key of body.keys) {
    meta[pid].keys++;
    if (key.is_plural) continue;
    const tr = key.translations || [];
    const enT = tr.find(t => t.language_iso === 'en');
    if (!enT || !enT.translation) continue;
    const enRaw = String(enT.translation); const en = clean(enRaw); const enKey = enRaw.trim().toLowerCase();
    for (const t of tr) {
      const iso = t.language_iso;
      if (iso === 'en' || PSEUDO.has(iso) || !t.translation || t.is_unverified) continue;
      const cs = (t.custom_translation_statuses || []).map(c => String(c.title || ''));
      if (cs.some(x => /AI|MT/i.test(x))) continue;
      const isHuman = t.is_reviewed || LINGUISTS.has(String(t.modified_by_email || '').toLowerCase());
      const s = S(iso); s.n++; if (isHuman) s.human++;
      const tg = clean(t.translation);
      if (/["\u201C\u201D]/.test(en)) { for (const ch of tg) { if ('"\u201C\u201D\u201E\u00AB\u00BB\u201A\u2018\u2019\u300C\u300D\u300E\u300F\u2039\u203A'.includes(ch)) bump(s.quotes, ch); } }
      const aS = (tg.match(/\p{L}'\p{L}/gu)||[]).length, aC = (tg.match(/\p{L}\u2019\p{L}/gu)||[]).length; s.apos.straight+=aS; s.apos.curly+=aC;
      for (const m of tg.matchAll(/(.)([?!:;])/gu)) { const prev = m[1]; const k = prev==='\u00A0'?'nbsp':prev==='\u202F'?'nnbsp':prev===' '?'space':'none'; if (m[2]===':' && /\d/.test(prev)) continue; bump(s.before[m[2]], k); }
      s.ellipsis.char += (tg.match(/\u2026/g)||[]).length; s.ellipsis.dots += (tg.match(/\.\.\./g)||[]).length;
      if (/\s&\s/.test(en)) { if (tg.includes('&')) s.amp.kept++; else s.amp.dropped++; }
      if (/\b\d+\.\d{1,2}\b/.test(en)) { if (/\d,\d{1,2}\b/.test(tg)) s.dec.comma++; else if (/\d\.\d{1,2}\b/.test(tg)) s.dec.dot++; }
      if (/\b\d{1,3},\d{3}\b/.test(en)) { if (/\d\.\d{3}\b/.test(tg)) s.thou.dot++; else if (/\d \d{3}\b/.test(tg)) s.thou.space++; else if (/\d\u00A0\d{3}\b/.test(tg)) s.thou.nbsp++; else if (/\d\u202F\d{3}\b/.test(tg)) s.thou.nnbsp++; else if (/\d,\d{3}\b/.test(tg)) s.thou.comma++; else if (/\d'\d{3}\b/.test(tg)) s.thou.apos++; }
      if (/[€$£]/.test(tg)) { if (/\d [€$£]/.test(tg)) s.cur.after_space++; else if (/\d[\u00A0\u202F][€$£]/.test(tg)) s.cur.after_nbsp++; else if (/\d[€$£]/.test(tg)) s.cur.after_none++; if (/[€$£] \d/.test(tg)) s.cur.before_space++; else if (/[€$£]\d/.test(tg)) s.cur.before_none++; }
      if (/\d\s?%/.test(tg)) { if (/\d %/.test(tg)) s.pct.space++; else if (/\d[\u00A0\u202F]%/.test(tg)) s.pct.nbsp++; else s.pct.none++; }
      if (/!\s*$/.test(en)) { if (/[!\uFF01]\s*$/.test(tg)) s.excl.kept++; else s.excl.dropped++; }
      if (tg.includes('\u00A0')) s.nbspStrings++; if (tg.includes('\u202F')) s.nnbspStrings++;
      if (s.time.length < 3 && /\b\d{1,2}(:\d{2})?\s?(AM|PM|am|pm)\b/.test(en)) s.time.push([enRaw.slice(0,90), String(t.translation).slice(0,120)]);
      if (s.date.length < 4 && (MONTH.test(en) && /\d/.test(en) || /\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/.test(en) || /MM\/DD|DD\/MM|YYYY/.test(en))) s.date.push([enRaw.slice(0,90), String(t.translation).slice(0,120)]);
      if (PROBESET.has(enKey)) { const arr = s.probes[enKey] = s.probes[enKey] || []; const v = String(t.translation).slice(0,80); if (arr.length < 2 && !arr.includes(v) && (isHuman || arr.length===0)) arr.push(v); }
      if (isHuman && s.reg.length < 5 && enRaw.length > 35 && enRaw.length < 130 && /\byour?\b/i.test(enRaw) && !/[<\[{]/.test(enRaw)) s.reg.push([enRaw, String(t.translation)]);
    }
  }
}
const out = Object.keys(L).sort().map(iso => ({ json: Object.assign({ iso }, L[iso]) }));
out.unshift({ json: { iso: '_meta', meta, errors } });
return out;
